refused_program.body:
map=config/renames.conf
test -f "$map" || exit 1
while IFS= read -r -d '' f; do
  case "$f" in
    config/renames.conf) continue ;;
    config/*.conf) ;;
    *) continue ;;
  esac
  test -f "$f" || continue
  tmp=$(mktemp) || exit 1
  if ! awk -v mapfile="$map" '
    BEGIN {
      while ((getline line < mapfile) > 0) {
        sub(/#.*/, "", line)
        eq = index(line, "=")
        if (eq == 0) continue
        old = substr(line, 1, eq - 1)
        new = substr(line, eq + 1)
        gsub(/^[[:space:]]+/, "", old)
        gsub(/[[:space:]]+$/, "", old)
        gsub(/^[[:space:]]+/, "", new)
        gsub(/[[:space:]]+$/, "", new)
        if (old != "" && new != "") {
          olds[++n] = old
          news[n] = new
        }
      }
    }
    {
      line = $0
      for (i = 1; i <= n; i++) {
        old = olds[i]
        new = news[i]
        if (match(line, /^[[:space:]]*/)) {
          ws = substr(line, 1, RLENGTH)
          rest = substr(line, RLENGTH + 1)
        } else {
          ws = ""
          rest = line
        }
        if (index(rest, old) == 1) {
          after = substr(rest, length(old) + 1)
          if (match(after, /^[[:space:]]*=/)) {
            line = ws new after
            break
          }
        }
      }
      print line
    }
  ' "$f" > "$tmp"; then
    rm -f "$tmp"
    exit 1
  fi
  if ! cmp -s "$f" "$tmp"; then
    if ! cat "$tmp" > "$f"; then
      rm -f "$tmp"
      exit 1
    fi
  fi
  rm -f "$tmp"
done < <(git ls-files --others --ignored --exclude-standard -z)

postconditions.probe:
map=config/renames.conf
test -f "$map" || exit 1
stale=1
while IFS= read -r -d '' f; do
  case "$f" in
    config/renames.conf) continue ;;
    config/*.conf) ;;
    *) continue ;;
  esac
  test -f "$f" || continue
  while IFS= read -r line; do
    case "$line" in
      ''|'#'*) continue ;;
    esac
    old=${line%%=*}
    old=$(printf '%s' "$old" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
    test -n "$old" || continue
    if awk -v old="$old" '
      {
        if (match($0, /^[[:space:]]*/)) {
          rest = substr($0, RLENGTH + 1)
        } else {
          rest = $0
        }
        if (index(rest, old) == 1) {
          after = substr(rest, length(old) + 1)
          if (after ~ /^[[:space:]]*=/) { found = 1; exit }
        }
      }
      END { exit(found ? 0 : 1) }
    ' "$f"; then
      stale=0
      break 2
    fi
  done < "$map"
done < <(git ls-files --others --ignored --exclude-standard -z)
test "$stale" -eq 1

