map=config/renames.conf
test -f "$map" || exit 1
bad=1
has_key() {
  awk -v key="$1" '
    {
      if (match($0, /^[[:space:]]*/)) {
        rest = substr($0, RLENGTH + 1)
      } else {
        rest = $0
      }
      if (index(rest, key) == 1) {
        after = substr(rest, length(key) + 1)
        if (after ~ /^[[:space:]]*=/) { found = 1; exit }
      }
    }
    END { exit(found ? 0 : 1) }
  ' "$2"
}
while IFS= read -r -d '' f; do
  case "$f" in
    config/renames.conf) continue ;;
    config/*.conf) ;;
    *) continue ;;
  esac
  test -f "$f" || continue
  while IFS= read -r line; do
    case "$line" in
      ''|'#'*) continue ;;
    esac
    old=${line%%=*}
    new=${line#*=}
    old=$(printf '%s' "$old" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
    new=$(printf '%s' "$new" | sed 's/#.*//; s/^[[:space:]]*//; s/[[:space:]]*$//')
    test -n "$old" && test -n "$new" || continue
    if has_key "$old" "$f" && has_key "$new" "$f"; then
      bad=0
      break 2
    fi
  done < "$map"
done < <(git ls-files --others --ignored --exclude-standard -z)
test "$bad" -eq 1
